from __future__ import annotations

import importlib.util
import pathlib
import sys
import types
import typing

import lcjson

# LeetCode's python3 snippets annotate with List/Optional/Dict and rely on the
# judge having pre-imported them. Seeding the module globals keeps the user's
# file byte-for-byte identical to what gets submitted.
INJECTED = {
    "ListNode": lcjson.ListNode,
    "TreeNode": lcjson.TreeNode,
}
for _name in dir(typing):
    if not _name.startswith("_"):
        INJECTED.setdefault(_name, getattr(typing, _name))


def load_solution(path: str) -> types.ModuleType:
    resolved = pathlib.Path(path).resolve()
    # A LeetCode filename such as 0001.two-sum.py is not a legal module name,
    # so the loader supplies its own.
    spec = importlib.util.spec_from_file_location("leetcode_solution", resolved)
    if spec is None or spec.loader is None:
        raise RuntimeError(f"cannot load {resolved}")

    module = importlib.util.module_from_spec(spec)
    module.__dict__.update(INJECTED)
    sys.modules[spec.name] = module
    sys.path.insert(0, str(resolved.parent))
    spec.loader.exec_module(module)
    return module
